.grid { display: grid; gap: 7px; width: 437px; margin: 5px 0 0 7px; }
.grid > b { display: block; height: 9px; background: #789; }
.g3 { grid-template-columns: repeat(3, 1fr); } .g6 { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; }
